def compress(s: str) -> str:
    """Return the run-length encoding of s, for example "aaabcc" -> "a3b1c2"."""
    if not s:
        return ""

    # Create a dictionary to count occurrences of each letter
    letter_counts = {}
    for char in s:
        if char in letter_counts:
            letter_counts[char] += 1
        else:
            letter_counts[char] = 1

    # Initialize the result string
    result = ""

    # Iterate over the letter counts
    for char, count in letter_counts.items():
        # Append the count to the result string
        result += str(count)

        # Determine if we should add the character to the result string with an 's' at the end
        if char.isupper() or char.islower():
            if count > 1:
                result += char.lower()
            elif count == 1:
                result += char.upper()

