def merge_sorted(a: list[int], b: list[int]) -> list[int]:
    if not a or not b:
        return []

    merged = []
    current = min(a, b)
    while a and b:
        if a[0] < b[0]:
            merged.append(current)
            a.pop(0)
        else:
            merged.append(current)
            b.pop(0)
        current = min(a, b)

    merged += a if a else b

    return merged

