    """Return the index of the first character that appears exactly once in s, or -1."""
    from collections import Counter
    char_count = Counter(s)

    # Filter characters that appear exactly once
    unique_chars = {char: count for char, count in char_count.items() if count == 1}

    # Return the index of the first unique character, or -1 if no such character exists
    return next((index for index, char in enumerate(s) if char in unique_chars), -1)
