def group_anagrams(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams; sort each group, then sort the groups."""
    # Create a dictionary where keys are sorted characters of the word and values are lists of words
    anagram_group = {}

    # Iterate over each word in the list
    for word in words:
        # Sort the characters of the word and find the sorted version
        sorted_word = ''.join(sorted(word))

        # If the sorted word is in the dictionary, append the word to the list of values
        if sorted_word in anagram_group:
            anagram_group[sorted_word].append(word)
        # If the sorted word is not in the dictionary, create a new list with the word
        else:
            anagram_group[sorted_word] = [word]

    # Convert the dictionary to a list of lists, where each inner list is a sorted group of words
    return sorted(anagram_group.items(), key=lambda x: (x[0], x[1]))
